For each value, track the last index where it appeared. When we see a value again, the subarray from the previous occurrence to the current occurrence has length (current - previous + 1). We want the minimum such length.

```python
import sys

def solve():
    input_data = sys.stdin.read().split()
    N = int(input_data[0])
    A = list(map(int, input_data[1:N+1]))

    last_seen = {}
    min_len = float('inf')

    for i, val in enumerate(A):
        if val in last_seen:
            length = i - last_seen[val] + 1
            min_len = min(min_len, length)
        last_seen[val] = i

    if min_len == float('inf'):
        print(-1)
    else:
        print(min_len)

solve()
```

